int save(FILE *handle) { /* called by mccode_main for NMX:SAVE */
  if (!handle) siminfo_init(NULL);

  /* call iteratively all components SAVE */
  class_Progress_bar_save(&_Origin_var);













































































  class_PSD_monitor_save(&_psdSample_var);

  class_Divergence_monitor_save(&_divAtSample_var);

  class_Divergence_monitor_save(&_divAtSampleOverview_var);

  class_TOFLambda_monitor_save(&_toflSample_var);

  class_DivLambda_monitor_save(&_divlSample_var);


  class_Monitor_nD_save(&_nD_Mantid_0_var);

  class_Monitor_nD_save(&_nD_Mantid_1_var);

  class_Monitor_nD_save(&_nD_Mantid_2_var);

  class_Monitor_nD_save(&_Structure_var);

  if (!handle) siminfo_close(); 

  return(0);
} /* save */

